SELECT DATE_TRUNC('WEEK', last_restock) AS week_start, STDDEV_SAMP(quantity) AS quantity_stddev, PERCENTILE_APPROX(quantity, 0.5) AS quantity_p50, SUM(quantity) AS total_quantity, COUNT(DISTINCT product_id) AS distinct_product_ids, PERCENTILE_APPROX(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles, BIT_AND(quantity) AS quantity_bit_and FROM inventory GROUP BY week_start HAVING quantity_bit_and < 1000
